export function isLixStorage(value) {
    if (!value || typeof value !== "object" || !("lixStorage" in value)) {
        return false;
    }
    const adapter = value.lixStorage;
    return Boolean(adapter &&
        typeof adapter === "object" &&
        adapter.version === 1 &&
        typeof adapter.connect === "function" &&
        adapter.config?.kind ===
            "filesystem");
}
